/bin/zsh -lc "node --input-type=module <<'JS'
import assert from 'node:assert/strict';
import { shouldInject } from './solution.mjs';
assert.equal(shouldInject('a', 'x'), true);
assert.equal(shouldInject('a', 'x'), false);
assert.equal(shouldInject('a', 'y'), true);
assert.equal(shouldInject('a', 'x'), false);
assert.equal(shouldInject('b', 'x'), true);
assert.equal(shouldInject('a', 'x', true), true);
assert.equal(shouldInject('a', 'x'), false);
assert.equal(shouldInject('a', 'y'), true);
assert.equal(shouldInject('b', 'x'), false);
for (const session of ['', null, undefined]) {
  assert.equal(shouldInject(session, 'x'), true);
  assert.equal(shouldInject(session, 'x'), true);
  assert.equal(shouldInject(session, 'x', true), true);
}
console.log('All local assertions passed.');
JS"

